SET statement_timeout='180s';
\pset format unaligned
\pset fieldsep '\t'
\pset footer off
WITH p AS (SELECT id, slug FROM entity WHERE slug IN ('adah-wife-of-esau','adin-who-sealed-the-covenant','admin','ahi-3','ahijah-8','ahijah-9','amariah-priest-with-zerubbabel','ariel-4','assir-3','azarel-6','azariah-19','azariah-21','azariah-23','azgad-who-sealed-the-covenant','bathshua','benaiah-the-trumpeting-priest','binnui-levite-with-zerubbabel','bunni-the-covenant-chief','chelub-father-of-ezri','edom-2','elasah-3','elasah-4','eleasah-3','eleasah-4','eliehoenai-3','eliehoenai-4','eliehoenai-5','eliehoenai-6','elihu-6','elihu-7','elihu-8','elioenai-7','elishah-2','elkanah-doorkeeper-of-the-ark','ezer-at-the-dedication','ezra-2','galal-who-dwelt-in-jerusalem','gazez-3','hachmoni-father-of-jashobeam','hakkoz-3','hasshub-4','heber-5','hezekiah-4','hizkijah-the-covenant-chief','hodiah-5','hodiah-6','hur-5','ishi-4','ishi-the-simeonite','ishmaiah-2','isshiah-5','ittai-son-of-ribai','jabin-king-of-canaan','jahaziel-the-trumpeting-priest','james-son-of-mary','jehohanan-10','jehohanan-11','jehohanan-13','jehohanan-14','jehohanan-15','jehonathan-10','jehonathan-11','jehonathan-12','jehonathan-13','jehonathan-14','jehonathan-15','jehonathan-16','jehonathan-3','jehonathan-4','jehonathan-5','jehonathan-6','jehonathan-7','jehonathan-8','jehonathan-9','jehoshaphat-5','jeiel-10','jeiel-9','jeiel-chief-of-the-levites','jeremoth-10','jeremoth-12','jeremoth-13','jeremoth-8','jeremoth-9','jerimoth-10','jerimoth-6','jerimoth-7','jerimoth-8','jerimoth-9','jeroham-father-of-jaresiah','jeshua-son-of-kadmiel','joel-son-of-azariah','johanan-11','johanan-12','johanan-14','joses-son-of-mary','jozabad-10','jozabad-9','kingjareb','kolaiah-3','levi-son-of-alphaeus','maacah-10','maaseiah-21','malchijah-12','malchijah-father-of-pashhur','meshezabel-3','meshullam-the-covenant-chief','micah-7','mijamin-4','nethanel-10','nethanel-8','oholibamah-wife-of-esau','pahath-moab-who-sealed-the-covenant','paltiel-2','parosh-who-sealed-the-covenant','pashhur-the-priest','raphah','raphah-3','sallu-4','shammah-6','shemer-3','shemer-4','shephatiah-9','simeon-5','tahath-6','tobiah-3','tobijah-3','tobijah-4','ucal','uzza-4','zaboud','zechariah-trumpeter-of-the-second-company','ziha-over-the-nethinims','zimri-5','zohar-3')),
v AS (SELECT DISTINCT ON (p.slug, ev.canonical_book, ev.canonical_chapter, ev.canonical_verse) p.slug, ev.canonical_book b, ev.canonical_chapter c, ev.canonical_verse n
      FROM p JOIN entity_verse ev ON ev.entity_id=p.id),
v2 AS (SELECT * FROM (SELECT v.*, row_number() OVER (PARTITION BY slug ORDER BY b,c,n) rn FROM v) x WHERE rn<=2)
SELECT v2.slug, v2.b||':'||v2.c||':'||v2.n, t.slug,
  (SELECT string_agg(w.text, ' ' ORDER BY w.position) FROM word w WHERE w.verse_id=vr.verse_id)
FROM v2 JOIN verse_reference vr ON vr.canonical_book=v2.b AND vr.canonical_chapter=v2.c AND vr.canonical_verse=v2.n AND vr.is_primary
JOIN verse vv ON vv.id=vr.verse_id JOIN text t ON t.id=vv.text_id AND t.slug IN ('RUSV','UBIO','KJV')
ORDER BY 1,2,3;
